    /** The shared cosmosdb classification table, embedded unchanged from spec/data-stores/cosmosdb.json. */
    private const COSMOSDB = <<<'JSON'
{
  "$comment": "Write-guard classification for Azure Cosmos DB for NoSQL, shared by every binding. Sourced from the Azure Cosmos DB REST API reference (learn.microsoft.com/rest/api/cosmos-db/: common request headers, documents, stored procedures, triggers, transactional batch, patch, change feed and query plan) and the operation types the SDKs expose (Node @azure/cosmos OperationType, .NET and Java OperationType). The unit is the operation type; a hook that sees only the HTTP request derives the operation type with the rules under fromRequest. Anything not listed is a write. See spec/data-stores.md.",
  "store": "cosmosdb",
  "version": 1,
  "source": "Azure Cosmos DB REST API reference (x-ms-version 2018-12-31 and later); SDK OperationType enums",
  "default": "write",
  "keyFormat": "The operation type name, compared case-insensitively and reported with the spelling below: Node's @azure/cosmos spells them in lower case (read, query, execute). Node's Execute is .NET and Java's ExecuteJavaScript, and Node's Query covers .NET's SqlQuery. Node sends its query-plan request as a read and its change-feed request as a query; both are reads either way.",
  "read": [
    "Read",
    "ReadFeed",
    "Query",
    "SqlQuery",
    "QueryPlan",
    "Head",
    "HeadFeed"
  ],
  "write": [
    "Create",
    "Upsert",
    "Replace",
    "Patch",
    "Delete",
    "Batch",
    "Execute",
    "ExecuteJavaScript"
  ],
  "rules": [
    "A request that names a pre-trigger or post-trigger (x-ms-documentdb-pre-trigger-include or x-ms-documentdb-post-trigger-include, the SDKs' preTriggerInclude and postTriggerInclude options) is a write whatever its operation type: triggers run only around writes, and their code can write.",
    "Executing a stored procedure (Execute, ExecuteJavaScript) is a write, even when the procedure only reads: the guard can't see its code.",
    "Batch is a write. It covers transactional batches and the SDKs' bulk mode, which sends batch requests with x-ms-cosmos-batch-atomic: false.",
    "Patch is a write, including a conditional patch whose filter predicate fails.",
    "Query, ReadFeed (including the change feed) and QueryPlan are reads: the Cosmos DB query language can't write.",
    "Reading or querying databases, containers, offers, partition key ranges, stored procedures, triggers and user-defined functions is a read. Creating, replacing or deleting any of them is a write.",
    "x-ms-cosmos-allow-tentative-writes is sent on every request, reads included, and says nothing about the operation."
  ],
  "fromRequest": {
    "$comment": "For hooks on the HTTP pipeline (Python and Go policies), which see the request rather than the SDK's operation type. Header names are case-insensitive; boolean header values compare case-insensitively with True.",
    "path": "The resource path alternates resource types and ids: /dbs/{db}/colls/{coll}/docs/{doc}. A path with an even number of segments addresses one resource; an odd number addresses a feed of the last resource type. The root path / reads the database account.",
    "order": [
      {
        "when": "a trigger header is present",
        "operation": "the derived type below, classified as a write"
      },
      {
        "when": "method GET, one resource",
        "operation": "Read"
      },
      {
        "when": "method GET, a feed or the account root",
        "operation": "ReadFeed"
      },
      {
        "when": "method HEAD, one resource",
        "operation": "Head"
      },
      {
        "when": "method HEAD, a feed",
        "operation": "HeadFeed"
      },
      {
        "when": "method POST and x-ms-cosmos-is-query-plan-request: True",
        "operation": "QueryPlan"
      },
      {
        "when": "method POST and x-ms-documentdb-isquery: True, or Content-Type application/query+json",
        "operation": "Query"
      },
      {
        "when": "method POST and x-ms-cosmos-is-batch-request: True",
        "operation": "Batch"
      },
      {
        "when": "method POST on one resource under sprocs (/dbs/{db}/colls/{coll}/sprocs/{sproc})",
        "operation": "ExecuteJavaScript"
      },
      {
        "when": "method POST and x-ms-documentdb-is-upsert: True",
        "operation": "Upsert"
      },
      {
        "when": "method POST, otherwise",
        "operation": "Create"
      },
      {
        "when": "method PUT",
        "operation": "Replace"
      },
      {
        "when": "method PATCH",
        "operation": "Patch"
      },
      {
        "when": "method DELETE",
        "operation": "Delete"
      },
      {
        "when": "anything else",
        "operation": "the method name, which is a write"
      }
    ],
    "target": "db.collection.name is the container id: the segment after colls. db.namespace is the database id: the segment after dbs."
  },
  "notes": {
    "Preview": "Cosmos DB can only roll back inside one logical partition, through a transactional batch the client builds up front. An arbitrary handler's writes can't be held back and discarded, so Cosmos DB runs in guard mode only.",
    "Credentials": "The authorization header (a master-key signature or an Entra ID token) and the account key are never captured."
  }
}
JSON;

    /** The shared firestore classification table, embedded unchanged from spec/data-stores/firestore.json. */
    private const FIRESTORE = <<<'JSON'
{
  "$comment": "Write-guard classification for Google Cloud Firestore (native mode), shared by every binding. Sourced from the Firestore RPC reference for google.firestore.v1.Firestore and google.firestore.admin.v1.FirestoreAdmin (cloud.google.com/firestore/docs/reference/rpc, firestore.proto and its google.api.http REST bindings). The unit is the RPC method name; a hook on the REST transport derives it with the rules under fromRest. Anything not listed is a write. See spec/data-stores.md.",
  "store": "firestore",
  "version": 1,
  "source": "google.firestore.v1 and google.firestore.admin.v1 RPC reference",
  "default": "write",
  "keyFormat": "The RPC method name, case-sensitive, from the gRPC path /google.firestore.v1.Firestore/<Method>. A method of any other service is a write unless listed under services.",
  "services": {
    "google.firestore.v1.Firestore": {
      "read": [
        "GetDocument",
        "ListDocuments",
        "BatchGetDocuments",
        "RunQuery",
        "RunAggregationQuery",
        "PartitionQuery",
        "Listen",
        "ListCollectionIds"
      ],
      "session": [
        "BeginTransaction",
        "Rollback"
      ],
      "write": [
        "CreateDocument",
        "UpdateDocument",
        "DeleteDocument",
        "Commit",
        "BatchWrite",
        "Write"
      ]
    },
    "google.firestore.admin.v1.FirestoreAdmin": {
      "readPrefixes": [
        "Get",
        "List"
      ],
      "rule": "A method whose name starts with Get or List is a read; every other admin method (CreateIndex, DeleteIndex, UpdateField, ExportDocuments, ImportDocuments, CreateDatabase, DeleteDatabase, RestoreDatabase, BulkDeleteDocuments and the rest) is a write."
    }
  },
  "conditional": {
    "Commit": "A write when its writes list has at least one entry. A Commit with no writes only ends a transaction that read and wrote nothing, so it is session. A hook that can't read the request message treats every Commit as a write."
  },
  "rules": [
    "Listen and RunQuery are reads even when they stream for a long time, and RunQuery, BatchGetDocuments and RunAggregationQuery stay reads when they begin a transaction (new_transaction).",
    "BeginTransaction and Rollback are allowed: they hold or release a transaction but change no data. Writes reach the database only through Commit, BatchWrite, Write and the document RPCs.",
    "Write is a bidirectional stream. Opening it is a write, so the guard refuses the stream before its first message.",
    "BatchWrite is a write even when every write in it would fail its precondition."
  ],
  "fromRest": {
    "$comment": "For hooks on the REST transport (an SDK's REST fallback, or plain HTTP). Paths start /v1/projects/{project}/databases/{database}/documents.",
    "verbs": {
      "batchGet": "BatchGetDocuments",
      "beginTransaction": "BeginTransaction",
      "commit": "Commit",
      "rollback": "Rollback",
      "runQuery": "RunQuery",
      "runAggregationQuery": "RunAggregationQuery",
      "partitionQuery": "PartitionQuery",
      "write": "Write",
      "listen": "Listen",
      "listCollectionIds": "ListCollectionIds",
      "batchWrite": "BatchWrite"
    },
    "order": [
      {
        "when": "the last path segment ends in :<verb>",
        "rpc": "the verbs entry for <verb>; an unknown verb is a write"
      },
      {
        "when": "method GET on a document (an even number of segments after documents)",
        "rpc": "GetDocument"
      },
      {
        "when": "method GET on a collection (an odd number of segments after documents)",
        "rpc": "ListDocuments"
      },
      {
        "when": "method PATCH",
        "rpc": "UpdateDocument"
      },
      {
        "when": "method DELETE",
        "rpc": "DeleteDocument"
      },
      {
        "when": "method POST on a collection",
        "rpc": "CreateDocument"
      },
      {
        "when": "anything else",
        "rpc": "the method name, which is a write"
      }
    ],
    "target": "db.collection.name is the collection id: the segment before the document id, or the last segment of a collection path. For a batch or query RPC it is the collection the request names (structuredQuery.from[0].collectionId), when there is one."
  },
  "notes": {
    "Preview": "A Firestore transaction can be rolled back, but it must do every read before its first write and its reads don't see its own buffered writes. Arbitrary handlers break both rules, so Firestore runs in guard mode only.",
    "Credentials": "OAuth access tokens, the authorization metadata and service-account keys are never captured."
  }
}
JSON;

